const val MOD = 1000000007L

fun power(n: Long, k: Long): Long {
    var result = 1L
    if (k > 0) {
        result *= power(n, k / 2)
        result %= MOD
        result *= result
        result %= MOD
        if (k % 2 == 1L) {
            result *= n
            result %= MOD
        }
    }
    return result
}

fun main() {
    val n = readln().toInt()
    val ans = (power(27, n.toLong()) - power(7, n.toLong())) % MOD
    println((ans + MOD) % MOD)
}

